--liquibase formatted sql

--changeset zofolio:case-study-v4-content
-- Textes sourcés de docs/content/case-studies-v4.md ; rubriques À FOURNIR et hindsight laissées NULL.
UPDATE project SET contribution = '{"fr": "J''ai tout construit seul, de zéro : le backend Spring Boot, le frontend Angular, leur mise en place et le déploiement en conteneurs.", "en": "I built all of it alone, from scratch: the Spring Boot back end, the Angular front end, their setup and the container deployment."}'::jsonb WHERE slug = 'oltre' AND contribution IS NULL;
UPDATE project SET takeaway = '{"fr": "L''application couvre le sport, avec mes activités Garmin, les dépenses, les tâches, les rendez-vous et les repas, plus un coach IA optionnel. Une configuration de production en HTTPS est en place, avec un seul point d''entrée exposé.", "en": "The app covers sport, with my Garmin activities, expenses, tasks, appointments and meals, plus an optional AI coach. A production setup over HTTPS is in place, with a single exposed entry point."}'::jsonb WHERE slug = 'oltre' AND takeaway = '{"fr": "Dépendre d''une API non officielle, c''est prévoir dès le départ où elle casse, et le dire clairement à l''utilisateur.", "en": "Depending on an unofficial API means planning from day one where it will break, and telling the user plainly."}'::jsonb;
UPDATE project SET contribution = '{"fr": "J''ai conçu et développé tout le système : le serveur Node qui reçoit les positions, les projette sur le tracé GPX et les diffuse en direct, la page publique, l''espace admin, les alertes et le mode simulation, puis le déploiement en conteneur derrière Caddy.", "en": "I designed and built the whole system: the Node server that receives positions, projects them onto the GPX route and broadcasts them live, the public page, the admin area, the alerts and the simulation mode, then the container deployment behind Caddy."}'::jsonb WHERE slug = 'zotracker' AND contribution IS NULL;
UPDATE project SET takeaway = '{"fr": "Les proches suivent ma position en direct sur une page publique, sans rien installer. Le serveur calcule l''allure et les heures de passage, et envoie des alertes. Le mode simulation permet de tout tester sans courir. Un fichier GPX piégé de 920 Ko, qui prenait 5,8 s à lire, se traite maintenant en 5 ms.", "en": "Loved ones follow my position live on a public page, with nothing to install. The server computes pace and passing times, and sends alerts. The simulation mode lets me test everything without running. A booby-trapped 920 KB GPX file that took 5.8 s to parse now takes 5 ms."}'::jsonb WHERE slug = 'zotracker' AND takeaway = '{"fr": "Une appli utilisée le jour J ne se juge pas à sa démo : elle se juge au pire moment de la course. D''où le mode simulation, pour tester sans courir.", "en": "An app used on race day isn''t judged by its demo: it''s judged at the worst moment of the race. Hence the simulation mode, to test without running."}'::jsonb;
UPDATE project SET contribution = '{"fr": "Nous étions quatre, et je me suis occupé du front et du back. Le projet comprend une application Android native et une API Quarkus avec PostgreSQL.", "en": "We were a team of four, and I worked on both the front end and the back end. The project has a native Android app and a Quarkus API with PostgreSQL."}'::jsonb WHERE slug = 'gfaim' AND contribution IS NULL;
UPDATE project SET takeaway = '{"fr": "Le projet de fin d''études a été livré : une API avec authentification par jeton, PostgreSQL et l''API Spoonacular, documentée en OpenAPI, et l''application Android native. Il n''est pas déployé.", "en": "The final-year project was delivered: an API with token authentication, PostgreSQL and the Spoonacular API, documented with OpenAPI, and the native Android app. It is not deployed."}'::jsonb WHERE slug = 'gfaim' AND takeaway = '{"fr": "Un bon résultat, et une bonne expérience d''équipe.", "en": "A good result, and a good team experience."}'::jsonb;
UPDATE project SET takeaway = NULL WHERE slug = 'trading-app' AND takeaway = '{"fr": "Travailler sur un système critique m''a appris la rigueur : analyser avant de coder, tester avant de livrer, et garder la tête froide quand tout va vite.", "en": "Working on a critical system taught me rigour: analyse before coding, test before shipping, and keep a cool head when everything moves fast."}'::jsonb;
UPDATE project SET stage = 'P2' WHERE slug = 'trading-app' AND stage IS NULL;
